390		if err != nil {
391			return Result{}, err
392		}
393		defer pipe.Destroy()
394	
395		pc := gemmPushConstants(M, N, K, block)
396		groupsX, groupsY := groupsFor(N, localSize), groupsFor(M, localSize)
397	
398		ns, err := TimeDispatch(pipe, groupsX, groupsY, 1, warmup, iters, pc)
399		if err != nil {
400			return Result{}, err
401		}
402	
403		flops := float64(2 * M * N * K)
404		return Result{
405			Op: "gemm", Variant: "naive", WeightFormat: "q8", BlockSize: block, Size: N,
406			NsPerIter: ns,
407			GFLOPS:    flops / (ns / 1e9) / 1e9,
408		}, nil
409	}
