550	// findCoopMatShape picks the first subgroup-scope shape matching aType/cType.
551	func findCoopMatShape(phys *vk.PhysicalDevice, aType, cType vk.ComponentType) (vk.CoopMatShape, bool, error) {
552		feat, err := phys.SupportedFeatures()
553		if err != nil {
554			return vk.CoopMatShape{}, false, err
555		}
556		if !feat.CoopMatrix {
557			return vk.CoopMatShape{}, false, nil
558		}
559		shapes, err := phys.CooperativeMatrixShapes()
560		if err != nil {
561			return vk.CoopMatShape{}, false, err
562		}
563		for _, s := range shapes {
564			if s.Scope == vk.ScopeSubgroup && s.AType == aType && s.BType == aType && s.CType == cType && s.ResultType == cType {
565				return s, true, nil
566			}
567		}
568		return vk.CoopMatShape{}, false, nil
569	}
