// gemvVariant is one reduction strategy (naive serial loop vs. one-subgroup-
// per-row) across all four weight-format shader binaries.
type gemvVariant struct {
	name      string
	shaderF32 []byte
	shaderF16 []byte
	shaderQ8  []byte
	shaderQ4  []byte
