		return Result{}, err
	}
	defer y.Destroy()

	pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{
		Buffers:          []*vk.Buffer{wBuf, scalesBuf, x, y},
		PushConstantSize: 12,
	})
