	if err != nil {
		return Result{}, err
	}

	weightBytes := float64(M * N * elemSize)
	flops := float64(2 * M * N)
	return Result{
		Op: "gemv", Variant: variant, WeightFormat: weightFormat, Size: N,
		NsPerIter: ns,
		GFLOPS:    flops / (ns / 1e9) / 1e9,
		GBPS:      weightBytes / (ns / 1e9) / 1e9,
	}, nil
}

