1	// Command bench runs the Vulkan compute benchmark suite for
2	// neural-network-inference-shaped operations (GEMM, GEMV, elementwise,
3	// reductions) across implementation flavours (naive/tiled/subgroup/
4	// cooperative-matrix; fp32/fp16/int8/int4 weights) on the local GPU,
5	// picking the Strix Halo iGPU if present.
6	package main
7	
8	import (
9		"flag"
10		"fmt"
11		"log"
12		"os"
13		"strconv"
14		"strings"
15	
16		"strix-halo-vulkan/bench"
17		"strix-halo-vulkan/vk"
18	)
19	
20	const strixHaloDeviceID = 0x1586
21	
22	func main() {
