1	// Package bench times the Vulkan compute kernels in shaders/ across the
2	// "flavours" (naive/tiled/subgroup/cooperative-matrix; fp32/fp16/int8/int4
3	// weights) that matter for neural-network inference, using GPU-side
4	// timestamp queries (vk.ComputePipeline.DispatchTimed) rather than
5	// wall-clock time.
6	package bench
7	
8	import (
9		"fmt"
10		"io"
11		"math/rand"
12		"os"
13		"text/tabwriter"
14	
15		"strix-halo-vulkan/vk"
16	)
17	
18	// Result is one measured data point.
19	type Result struct {
20		Op           string
21		Variant      string
22		WeightFormat string // "fp32", "fp16", "q8", "q4", or "" if not applicable
23		BlockSize    int    // quantization block size, 0 if not applicable
24		Size         int    // case-defined primary size (vector/matrix dimension)
25		NsPerIter    float64
26		GFLOPS       float64 // 0 if not a compute-bound op
27		GBPS         float64 // 0 if not a bandwidth-bound op
28	}
29	
30	// maxBatchNs bounds how long any single DispatchTimed call (a batch of
31	// back-to-back dispatches recorded into one command buffer) is allowed to
32	// run. Slow kernels (e.g. naive GEMM at large N) can take seconds per
33	// iteration; batching a fixed iteration count regardless of that risks
34	// exceeding the kernel driver's GPU-hang watchdog (amdgpu's default TDR is
35	// commonly ~10s) and getting VK_ERROR_DEVICE_LOST, which poisons the device
36	// for every case still to run. 500ms leaves ample margin under that.
37	const maxBatchNs = 500_000_000
38	
39	// TimeDispatch measures nanoseconds/iteration for one dispatch shape. It
40	// first probes with a single iteration (which also serves as one warmup
41	// dispatch) to estimate per-iteration cost, then caps both the remaining
42	// warmup dispatches and the timed batch to maxBatchNs worth of iterations —
43	// so a very slow kernel is measured with fewer iterations rather than
44	// risking a driver timeout.
45	func TimeDispatch(pipe *vk.ComputePipeline, groupsX, groupsY, groupsZ, warmup, iters uint32, pushConstants []byte) (float64, error) {
46		probe, err := pipe.DispatchTimed(groupsX, groupsY, groupsZ, 1, pushConstants)
47		if err != nil {
48			return 0, err
49		}
50		probeNs := float64(probe.Nanoseconds())
51		if probeNs <= 0 {
52			probeNs = 1
53		}
54		capToBudget := func(n uint32) uint32 {
55			maxByBudget := uint32(maxBatchNs / probeNs)
56			if maxByBudget < 1 {
57				maxByBudget = 1
58			}
59			if n > maxByBudget {
60				return maxByBudget
61			}
62			return n
63		}
64	
65		if warmup > 1 {
66			if _, err := pipe.DispatchTimed(groupsX, groupsY, groupsZ, capToBudget(warmup-1), pushConstants); err != nil {
67				return 0, err
68			}
69		}
70		actualIters := capToBudget(iters)
71		d, err := pipe.DispatchTimed(groupsX, groupsY, groupsZ, actualIters, pushConstants)
72		if err != nil {
73			return 0, err
74		}
75		return float64(d.Nanoseconds()) / float64(actualIters), nil
76	}
77	
78	// PrintTable writes a human-readable results table to w.
79	func PrintTable(w io.Writer, results []Result) {
80		tw := tabwriter.NewWriter(w, 0, 4, 2, ' ', 0)
81		fmt.Fprintln(tw, "OP\tVARIANT\tFORMAT\tBLOCK\tSIZE\tNS/ITER\tGFLOP/S\tGB/S")
82		for _, r := range results {
83			gflops, gbps, block := "-", "-", "-"
84			if r.GFLOPS > 0 {
85				gflops = fmt.Sprintf("%.2f", r.GFLOPS)
86			}
87			if r.GBPS > 0 {
88				gbps = fmt.Sprintf("%.2f", r.GBPS)
89			}
90			if r.BlockSize > 0 {
91				block = fmt.Sprintf("%d", r.BlockSize)
92			}
93			fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%d\t%.1f\t%s\t%s\n",
94				r.Op, r.Variant, r.WeightFormat, block, r.Size, r.NsPerIter, gflops, gbps)
95		}
96		tw.Flush()
97	}
98	
99	// WriteCSV writes results to path in the format described in the plan:
100	// op,variant,weight_format,block_size,size,ns_per_iter,gflops,gbps.
101	func WriteCSV(path string, results []Result) error {
102		f, err := os.Create(path)
103		if err != nil {
104			return err
105		}
106		defer f.Close()
107		fmt.Fprintln(f, "op,variant,weight_format,block_size,size,ns_per_iter,gflops,gbps")
108		for _, r := range results {
109			fmt.Fprintf(f, "%s,%s,%s,%d,%d,%.3f,%.4f,%.4f\n",
110				r.Op, r.Variant, r.WeightFormat, r.BlockSize, r.Size, r.NsPerIter, r.GFLOPS, r.GBPS)
111		}
112		return nil
113	}
114	
115	func randomFloats(n int) []float32 {
116		r := rand.New(rand.NewSource(42))
117		out := make([]float32, n)
118		for i := range out {
119			out[i] = r.Float32()*2 - 1 // [-1, 1)
120		}
121		return out
122	}
123	
124	func groupsFor(n, localSize int) uint32 {
125		return uint32((n + localSize - 1) / localSize)
126	}
